import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Meter reset and rollover","description":"","frontmatter":{"order":2,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/05.hintergrund/02.zaehler-reset.md"},"headers":[],"relativePath":"adapter/sourceanalytix/hintergrund/zaehler-reset.md","filePath":"adapter/sourceanalytix/hintergrund/zaehler-reset.md","lastUpdated":null}'),d={name:"adapter/sourceanalytix/hintergrund/zaehler-reset.md"};function s(n,e,i,h,l,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="meter-reset-and-rollover" tabindex="-1">Meter reset and rollover <a class="header-anchor" href="#meter-reset-and-rollover" aria-label="Permalink to &quot;Meter reset and rollover&quot;">​</a></h1><p><a id="device-reset-detected-mean-reset"></a></p><h2 id="what-does-device-reset-detected-mean-and-how-does-reset-detection-work" tabindex="-1">What does &quot;Device reset detected&quot; mean and how does reset detection work? <a class="header-anchor" href="#what-does-device-reset-detected-mean-and-how-does-reset-detection-work" aria-label="Permalink to &quot;What does &quot;Device reset detected&quot; mean and how does reset detection work?&quot;">​</a></h2><p>It&#39;s a warning, not an error. The source&#39;s meter reading dropped clearly, for example after a restart, power failure, overflow or meter swap, and SourceAnalytix keeps counting on top of the previous total. No negative values are created.</p><h3 id="the-terms" tabindex="-1">The terms <a class="header-anchor" href="#the-terms" aria-label="Permalink to &quot;The terms&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Target unit</td><td>the unit of the price definition that everything is calculated in</td></tr><tr><td>Device value</td><td>the source datapoint&#39;s value in the target unit; can drop back</td></tr><tr><td>Total</td><td><code>cumulativeReading</code>, SourceAnalytix&#39;s own meter reading; with reset detection it never drops</td></tr><tr><td>Offset</td><td>total = device value + offset; shown on the source under &quot;For experts&quot; as <code>valueAtDeviceReset</code></td></tr><tr><td>Start value</td><td>the total at the start of a period; consumption = total − start value</td></tr><tr><td>Threshold</td><td>the largest drop that still counts as measurement jitter, default 1</td></tr></tbody></table><h3 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h3><ol><li><strong>Equal or higher:</strong> the value is taken over.</li><li><strong>Lower, up to the threshold:</strong> measurement jitter, the value is ignored.</li><li><strong>Clearly lower:</strong> a possible reset. SourceAnalytix keeps the total and waits for the next value (&quot;Waiting for another reading …&quot;).</li><li><strong>The next value decides:</strong> if it is close to the old reading again, it was an outlier (&quot;Rejected a possible device reset&quot;). If it stays low, the reset is confirmed (&quot;Device reset detected …&quot;) and the offset is set anew. If the old reading comes back in one step after a confirmed reset, SourceAnalytix undoes the reset (&quot;Rolled back the device reset …&quot;).</li></ol><p>Example with a threshold of 1 kWh, meter at 1,000 kWh, at 0 after a power failure:</p><table tabindex="0"><thead><tr><th>Device value</th><th>Offset</th><th>Total</th></tr></thead><tbody><tr><td>1,000 kWh</td><td>0</td><td>1,000 kWh</td></tr><tr><td>0 kWh</td><td>0</td><td>1,000 kWh (waiting)</td></tr><tr><td>0.4 kWh</td><td>1,000</td><td>1,000.4 kWh</td></tr></tbody></table><p>Only what the device counted between its last value before the reset and the first one after it is lost. If SourceAnalytix was stopped during the reset, it detects it with the first value after the start, as long as the device hasn&#39;t overtaken the old reading yet. Power sources have no reset detection.</p><p>Without reset detection, SourceAnalytix takes over every drop, and the total and periods drop with it. This is only meant for sources that are allowed to drop.</p><p><strong>See also:</strong> <a href="./../referenz/einstellungen#threshold-disabling-reset-detection-work">Threshold and turning it off</a> · <a href="./../anleitungen/zaehlerstaende-korrigieren#meter-restarts-after-power-loss">Meter restarts at 0 after a power failure</a></p><p><a id="counter-reset-0-daily-happens"></a></p><h2 id="counter-that-is-reset-to-0-every-day-what-happens-internally" tabindex="-1">Counter that is reset to 0 every day: what happens internally? <a class="header-anchor" href="#counter-that-is-reset-to-0-every-day-what-happens-internally" aria-label="Permalink to &quot;Counter that is reset to 0 every day: what happens internally?&quot;">​</a></h2><p>With reset detection, the nightly drop to 0 is an ordinary reset: the total keeps going, and only a small remainder is lost each night. Without reset detection, the total drops, and the previous day&#39;s consumption is subtracted again.</p><p>Example with a threshold of 0.1 kWh, daily counter at 4.2 kWh in the evening:</p><table tabindex="0"><thead><tr><th>Time</th><th>Device value</th><th>Total</th><th>What happens</th></tr></thead><tbody><tr><td>23:58</td><td>4.2 kWh</td><td>1,004.2 kWh</td><td>–</td></tr><tr><td>0:00</td><td>–</td><td>1,004.2 kWh</td><td>period rollover, the new day starts at 0</td></tr><tr><td>0:01</td><td>0 kWh</td><td>1,004.2 kWh</td><td>waiting</td></tr><tr><td>0:10</td><td>0.05 kWh</td><td>1,004.25 kWh</td><td>reset confirmed, today 0.05 kWh</td></tr></tbody></table><p>It doesn&#39;t matter whether the device drops back shortly before or after midnight. If the threshold is larger than the daily consumption, the drop counts as jitter, and the start of the new day is lost. The wizard marks daily counters as &quot;daily counter&quot;; if possible, use the device&#39;s total counter.</p><p><strong>See also:</strong> <a href="./../anleitungen/zaehlerstaende-korrigieren#meter-restarts-after-power-loss">My meter restarts at 0 every day</a> · <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Meter or power?</a></p>',20)])])}const f=t(d,[["render",s]]);export{p as __pageData,f as default};
